let mode='tdm',started=false,paused=false,ammo=30,reserve=180,reloading=false,fireHeld=false,fireCooldown=0,scoreBlue=0,scoreRed=0,timeLeft=1080,gameClock=0,hitTimer=0,damageFlash=0,weaponIndex=0,weather=0,dayPhase=.42;const weapons=[{name:'M4A1 CARBINE',mag:30,reserve:180,delay:.105,damage:34},{name:'M9 SERVICE PISTOL',mag:15,reserve:90,delay:.24,damage:39},{name:'M1014 BREACHER',mag:8,reserve:48,delay:.65,damage:19}];let audioCtx;function sound(freq,dur,volume=.07,type='square'){try{audioCtx??=new AudioContext();let osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,audioCtx.currentTime);osc.frequency.exponentialRampToValueAtTime(Math.max(28,freq*.38),audioCtx.currentTime+dur);gain.gain.setValueAtTime(volume,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+dur);}catch{}}
const keys={};window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(!started)return;if(e.code==='KeyR')reload();if(e.code==='Digit1')setWeapon(0);if(e.code==='Digit2')setWeapon(1);if(e.code==='Digit3')setWeapon(2);if(e.code==='Escape'&&started)togglePause();if(e.code==='Space'&&!player.crouch)jump();if(e.code==='ControlLeft')player.crouch=true;});window.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='ControlLeft')player.crouch=false;});
function setWeapon(i){weaponIndex=i;ammo=weapons[i].mag;reserve=weapons[i].reserve;reloading=false;$('#weaponName').textContent=weapons[i].name;$('#ammo').textContent=ammo;$('#reserve').textContent=reserve;$('#firemode').textContent=i===0?'AUTO':i===1?'SEMI':'PUMP';}
function reload(){if(reloading||ammo===weapons[weaponIndex].mag||reserve<=0)return;reloading=true;$('#toast').textContent='RELOADING';$('#toast').classList.add('show');sound(120,.14,.035,'triangle');setTimeout(()=>{let w=weapons[weaponIndex],n=Math.min(w.mag-ammo,reserve);ammo+=n;reserve-=n;reloading=false;$('#ammo').textContent=ammo;$('#reserve').textContent=reserve;$('#toast').classList.remove('show');sound(280,.07,.025,'triangle');},weaponIndex===2?1800:1250);}
function startGame(){started=true;paused=false;$('#overlay').classList.add('hidden');$('#hud').classList.add('active');$('#banner').textContent='OPERATION IRON TIDE';$('#banner').classList.add('show');setTimeout(()=>$('#banner').classList.remove('show'),2100);try{sceneCanvas.requestPointerLock?.();}catch{}if(audioCtx?.state==='suspended')audioCtx.resume();}
