+function updatePlayer(dt){let forward=(keys.KeyW?1:0)-(keys.KeyS?1:0)-touchMove.y,side=(keys.KeyD?1:0)-(keys.KeyA?1:0)+touchMove.x;let len=Math.hypot(forward,side)||1;forward/=len;side/=len;let sprint=(keys.ShiftLeft||keys.ShiftRight)&&stamina>0&&!player.crouch;let speed=player.crouch?4.3:sprint?12.5:7.3;if(sprint&&len>1.01)stamina=Math.max(0,stamina-dt*20);else stamina=Math.min(100,stamina+dt*12);let dx=(-Math.sin(player.yaw)*forward+Math.cos(player.yaw)*side)*speed*dt,dz=(-Math.cos(player.yaw)*forward-Math.sin(player.yaw)*side)*speed*dt;if(!collides(player.x+dx,player.z))player.x+=dx;if(!collides(player.x,player.z+dz))player.z+=dz;player.speed=Math.hypot(dx,dz)/Math.max(dt,.001);if(jumpVelocity){jumpHeight+=jumpVelocity*dt;jumpVelocity-=15*dt;if(jumpHeight<=0){jumpHeight=0;jumpVelocity=0;}}let headY=player.crouch?1.12:1.72;camera.position.set(player.x,heightAt(player.x,player.z)+headY+jumpHeight,player.z);camera.rotation.set(player.pitch,player.yaw,0,'YXZ');let aim=player.aim?1:0;camera.fov=THREE.MathUtils.lerp(camera.fov,aim?51:73,.15);camera.updateProjectionMatrix();weaponRoot.position.x=THREE.MathUtils.lerp(weaponRoot.position.x,aim?.12:.38,.12);weaponRoot.position.y=THREE.MathUtils.lerp(weaponRoot.position.y,aim?-.22:-.3,.12);}
